  1→import { useState } from "react";
  2→import { useQuery } from "@tanstack/react-query";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import { useAuth } from "@/hooks/useAuth";
  5→import {
  6→  Dialog,
  7→  DialogContent,
  8→  DialogDescription,
  9→  DialogHeader,
 10→  DialogTitle,
 11→  DialogTrigger,
 12→} from "@/components/ui/dialog";
 13→import { Button } from "@/components/ui/button";
 14→import { Input } from "@/components/ui/input";
 15→import { Badge } from "@/components/ui/badge";
 16→import { toast } from "sonner";
 17→import { Coins, Loader2, ShoppingCart, Sparkles, Crown, Wallet } from "lucide-react";
 18→import SubscriptionDialog from "@/components/SubscriptionDialog";
 19→
 20→interface BuyCreditsDialogProps {
 21→  trigger?: React.ReactNode;
 22→}
 23→
 24→const QUICK_AMOUNTS = [5, 10, 25, 50];
 25→
 26→const BuyCreditsDialog = ({ trigger }: BuyCreditsDialogProps) => {
 27→  const { user } = useAuth();
 28→  const [open, setOpen] = useState(false);
 29→  const [amount, setAmount] = useState("");
 30→  const [buying, setBuying] = useState(false);
 31→
 32→  const { data: config } = useQuery({
 33→    queryKey: ["platform_config_topup"],
 34→    queryFn: async () => {
 35→      const { data, error } = await supabase
 36→        .from("platform_config")
 37→        .select("payg_per_resume_cost, topup_min_amount")
 38→        .limit(1)
 39→        .single();
 40→      if (error) throw error;
 41→      return data as any;
 42→    },
 43→  });
 44→
 45→  const perResumeCost = config?.payg_per_resume_cost ?? 0.07;
 46→  const minAmount = config?.topup_min_amount ?? 1;
 47→  const numericAmount = parseFloat(amount) || 0;
 48→  const calculatedCredits = perResumeCost > 0 ? Math.floor(numericAmount / perResumeCost) : 0;
 49→  const isValid = numericAmount >= minAmount;
 50→
 51→  const handleBuy = async () => {
 52→    if (!user || !isValid) return;
 53→    setBuying(true);
 54→
 55→    try {
 56→      const { data, error } = await supabase.functions.invoke("create-dodo-checkout", {
 57→        body: {
 58→          topup_amount: numericAmount,
 59→          return_url: `${window.location.origin}/payment/callback`,
 60→        },
 61→      });
 62→
 63→      if (error) throw error;
 64→
 65→      if (!data?.checkout_url) {
 66→        toast.error(data?.error || "Failed to create checkout session");
 67→        return;
 68→      }
 69→
 70→      window.location.href = data.checkout_url;
 71→    } catch (err: any) {
 72→      toast.error(err.message);
 73→    } finally {
 74→      setBuying(false);
 75→    }
 76→  };
 77→
 78→  return (
 79→    <Dialog open={open} onOpenChange={setOpen}>
 80→      <DialogTrigger asChild>
 81→        {trigger || (
 82→          <Button variant="outline" className="gap-2">
 83→            <ShoppingCart className="h-4 w-4" />
 84→            Buy Credits
 85→          </Button>
 86→        )}
 87→      </DialogTrigger>
 88→      <DialogContent className="sm:max-w-md">
 89→        <DialogHeader>
 90→          <DialogTitle className="flex items-center gap-2">
 91→            <Sparkles className="h-5 w-5 text-primary" />
 92→            Add Credits
 93→          </DialogTitle>
 94→          <DialogDescription>
 95→            Enter any amount to recharge your wallet. Credits never expire.
 96→          </DialogDescription>
 97→        </DialogHeader>
 98→
 99→        <div className="space-y-4 pt-2">
100→          {/* Quick amount buttons */}
101→          <div className="flex gap-2 flex-wrap">
102→            {QUICK_AMOUNTS.filter(a => a >= minAmount).map((a) => (
103→              <Button
104→                key={a}
105→                variant={numericAmount === a ? "default" : "outline"}
106→                size="sm"
107→                className="flex-1 min-w-[60px]"
108→                onClick={() => setAmount(String(a))}
109→              >
110→                ${a}
111→              </Button>
112→            ))}
113→          </div>
114→
115→          {/* Amount input */}
116→          <div>
117→            <label className="text-sm font-medium text-foreground mb-1.5 block">
118→              Custom Amount (USD)
119→            </label>
120→            <div className="relative">
121→              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
122→              <Input
123→                type="number"
124→                step="0.5"
125→                min={minAmount}
126→                placeholder={String(minAmount)}
127→                value={amount}
128→                onChange={(e) => setAmount(e.target.value)}
129→                className="pl-7 text-lg font-semibold"
130→                autoFocus
131→              />
132→            </div>
133→            <p className="text-[11px] text-muted-foreground mt-1">
134→              Minimum: ${minAmount}
135→            </p>
136→          </div>
137→
138→          {/* Credit preview */}
139→          {numericAmount > 0 && (
140→            <div className="rounded-lg bg-accent/50 border border-border p-4 text-center">
141→              <div className="flex items-center justify-center gap-2">
142→                <Wallet className="h-5 w-5 text-primary" />
143→                <span className="text-sm text-muted-foreground">You'll get</span>
144→              </div>
145→              <div className="flex items-center justify-center gap-2 mt-1">
146→                <Badge className="gap-1 text-base px-3 py-1">
147→                  <Coins className="h-4 w-4" />
148→                  {calculatedCredits} credits
149→                </Badge>
150→              </div>
151→              <p className="text-[11px] text-muted-foreground mt-2">
152→                1 credit = 1 resume ranked • ${perResumeCost}/credit
153→              </p>
154→            </div>
155→          )}
156→
157→          {/* Pay button */}
158→          <Button
159→            className="w-full"
160→            size="lg"
161→            onClick={handleBuy}
162→            disabled={buying || !isValid}
163→          >
164→            {buying ? (
165→              <Loader2 className="h-4 w-4 animate-spin mr-2" />
166→            ) : null}
167→            {numericAmount > 0 ? `Pay $${numericAmount.toFixed(2)}` : "Enter an amount"}
168→          </Button>
169→        </div>
170→
171→        {/* Subscription upsell */}
172→        <div className="rounded-lg bg-primary/5 border border-primary/20 px-4 py-3 flex items-center justify-between">
173→          <div className="flex items-center gap-2">
174→            <Crown className="h-4 w-4 text-primary" />
175→            <p className="text-xs font-medium text-foreground">Save more with a subscription plan</p>
176→          </div>
177→          <SubscriptionDialog
178→            trigger={
179→              <Button variant="ghost" size="sm" className="h-7 text-xs text-primary hover:text-primary gap-1">
180→                View Plans →
181→              </Button>
182→            }
183→          />
184→        </div>
185→      </DialogContent>
186→    </Dialog>
187→  );
188→};
189→
190→export default BuyCreditsDialog;
191→

  1→// @ts-nocheck
  2→// deno-lint-ignore-file no-explicit-any
  3→/// <reference lib="deno.ns" />
  4→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
  5→import DodoPayments from "https://esm.sh/dodopayments@2.4.1";
  6→import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
  7→
  8→const corsHeaders = {
  9→  "Access-Control-Allow-Origin": "*",
 10→  "Access-Control-Allow-Headers":
 11→    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
 12→};
 13→
 14→Deno.serve(async (req) => {
 15→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 16→
 17→  try {
 18→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 19→    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
 20→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 21→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
 22→    const DODO_ENV = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";
 23→
 24→    if (!DODO_API_KEY) {
 25→      return new Response(
 26→        JSON.stringify({ error: "Dodo Payments API key not configured" }),
 27→        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
 28→      );
 29→    }
 30→
 31→    // Authenticate user
 32→    const authHeader = req.headers.get("Authorization");
 33→    if (!authHeader) {
 34→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
 35→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 36→      });
 37→    }
 38→
 39→    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
 40→      global: { headers: { Authorization: authHeader } },
 41→    });
 42→    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
 43→    if (userError || !user) {
 44→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
 45→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 46→      });
 47→    }
 48→
 49→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 50→    const body = await req.json();
 51→    const { topup_amount, plan_id, return_url } = body as Record<string, unknown>;
 52→
 53→    if (!topup_amount && !plan_id) {
 54→      return new Response(JSON.stringify({ error: "topup_amount or plan_id required" }), {
 55→        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
 56→      });
 57→    }
 58→
 59→    let productId: string;
 60→    let amount: number;
 61→    let credits: number;
 62→    let currency = "USD";
 63→    let itemName: string;
 64→    let itemType: "topup" | "plan";
 65→    let itemId: string | null = null;
 66→
 67→    if (topup_amount) {
 68→      // ─── WALLET TOP-UP FLOW ───
 69→      const topupNum = Number(topup_amount);
 70→      if (isNaN(topupNum) || topupNum <= 0) {
 71→        return new Response(JSON.stringify({ error: "Invalid topup_amount" }), {
 72→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
 73→        });
 74→      }
 75→
 76→      // Get platform config for min amount, per-resume cost, and dodo product id
 77→      const { data: config, error: configError } = await supabase
 78→        .from("platform_config")
 79→        .select("topup_min_amount, payg_per_resume_cost, topup_dodo_product_id")
 80→        .limit(1)
 81→        .single();
 82→
 83→      if (configError || !config) {
 84→        return new Response(JSON.stringify({ error: "Platform config not found" }), {
 85→          status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
 86→        });
 87→      }
 88→
 89→      const minAmount = config.topup_min_amount ?? 1;
 90→      if (topupNum < minAmount) {
 91→        return new Response(JSON.stringify({ error: `Minimum top-up amount is $${minAmount}` }), {
 92→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
 93→        });
 94→      }
 95→
 96→      if (!config.topup_dodo_product_id) {
 97→        return new Response(JSON.stringify({ error: "Wallet top-up not configured. Admin must create the Dodo product first." }), {
 98→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
 99→        });
100→      }
101→
102→      const perResumeCost = config.payg_per_resume_cost ?? 0.07;
103→      credits = Math.floor(topupNum / perResumeCost);
104→      if (credits < 1) {
105→        return new Response(JSON.stringify({ error: "Amount too small to purchase any credits" }), {
106→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
107→        });
108→      }
109→
110→      productId = config.topup_dodo_product_id;
111→      amount = Math.round(topupNum * 100); // cents
112→      itemName = `Wallet Top-Up $${topupNum}`;
113→      itemType = "topup";
114→    } else {
115→      // ─── PLAN SUBSCRIPTION FLOW (unchanged) ───
116→      const { data: plan, error } = await supabase
117→        .from("plans")
118→        .select("*")
119→        .eq("id", plan_id)
120→        .eq("active", true)
121→        .single();
122→      if (error || !plan) {
123→        return new Response(JSON.stringify({ error: "Plan not found or inactive" }), {
124→          status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
125→        });
126→      }
127→      if (!plan.dodo_product_id) {
128→        return new Response(JSON.stringify({ error: "This plan is not configured for Dodo Payments. Add a Dodo Product ID in admin." }), {
129→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
130→        });
131→      }
132→      productId = plan.dodo_product_id;
133→      amount = Math.round(plan.price * 100);
134→      credits = plan.credits;
135→      itemName = plan.name;
136→      itemType = "plan";
137→      itemId = String(plan_id);
138→    }
139→
140→    // Build return URL
141→    const baseReturnUrl =
142→      (typeof return_url === "string" && return_url) ||
143→      `${req.headers.get("origin") || "https://rankora.co"}/payment/callback`;
144→
145→    // 1) Create local payment record
146→    const insertPayload: any = {
147→      user_id: user.id,
148→      amount,
149→      currency,
150→      credits_purchased: credits,
151→      status: "created",
152→      payment_gateway: "dodo",
153→    };
154→    if (itemType === "plan" && itemId) {
155→      insertPayload.plan_id = itemId;
156→    }
157→
158→    const insertRes = await supabase
159→      .from("payments")
160→      .insert(insertPayload)
161→      .select("id")
162→      .single();
163→
164→    if (insertRes.error || !insertRes.data) {
165→      console.error("Failed to create local payment record:", insertRes.error?.message);
166→      await logSystemError({
167→        function_name: "create-dodo-checkout",
168→        error_type: "PAYMENT_RECORD_CREATE",
169→        severity: "critical",
170→        error_message: `Failed to create local payment record: ${insertRes.error?.message}`,
171→        user_id: user.id,
172→      });
173→      return new Response(JSON.stringify({ error: "Failed to create local payment record" }), {
174→        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
175→      });
176→    }
177→
178→    const localPaymentId = insertRes.data.id as string;
179→    const returnUrlWithLocalPaymentId = `${baseReturnUrl}${baseReturnUrl.includes("?") ? "&" : "?"}local_payment_id=${encodeURIComponent(localPaymentId)}`;
180→
181→    // 2) Create Dodo Checkout Session
182→    const isLive = DODO_ENV === "live_mode";
183→    const client = new DodoPayments({
184→      bearerToken: DODO_API_KEY,
185→      baseURL: isLive
186→        ? "https://live.dodopayments.com"
187→        : "https://test.dodopayments.com",
188→    });
189→
190→    const cartItem: any = { product_id: productId, quantity: 1 };
191→    if (itemType === "topup") {
192→      cartItem.amount = amount; // dynamic amount in cents for PWYW product
193→    }
194→
195→    const session = await client.checkoutSessions.create({
196→      product_cart: [cartItem],
197→      customer: {
198→        email: user.email ?? "",
199→        name: user.email?.split("@")[0] || "Customer",
200→      },
201→      billing_address: {
202→        street: "NA",
203→        city: "NA",
204→        state: "NA",
205→        country: "US",
206→        zipcode: "00000",
207→      },
208→      return_url: returnUrlWithLocalPaymentId,
209→      metadata: {
210→        local_payment_id: localPaymentId,
211→        user_id: user.id,
212→        item_type: itemType,
213→        item_id: itemId || "",
214→        item_name: itemName,
215→        credits: String(credits),
216→      } as Record<string, string>,
217→    });
218→
219→    // 3) Persist the Dodo checkout session id
220→    if ((session as Record<string, unknown>).session_id) {
221→      await supabase
222→        .from("payments")
223→        .update({ dodo_checkout_session_id: (session as Record<string, string>).session_id })
224→        .eq("id", localPaymentId);
225→    }
226→
227→    return new Response(
228→      JSON.stringify({
229→        checkout_url: (session as Record<string, string>).checkout_url,
230→        checkout_session_id: (session as Record<string, string>).session_id,
231→        payment_id: localPaymentId,
232→      }),
233→      { headers: { ...corsHeaders, "Content-Type": "application/json" } },
234→    );
235→  } catch (err: unknown) {
236→    console.error("create-dodo-checkout error:", err);
237→    await logSystemError({
238→      function_name: "create-dodo-checkout",
239→      error_type: "CHECKOUT_ERROR",
240→      severity: "critical",
241→      error_message: errorToMessage(err),
242→      error_stack: errorToStack(err),
243→    });
244→    return new Response(
245→      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
246→      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
247→    );
248→  }
249→});
250→

  1→// @ts-nocheck
  2→// deno-lint-ignore-file no-explicit-any
  3→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
  4→import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
  5→
  6→const corsHeaders = {
  7→  "Access-Control-Allow-Origin": "*",
  8→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
  9→};
 10→
 11→const PAID_STATUSES = new Set(["paid", "completed", "succeeded", "success"]);
 12→const FAILED_STATUSES = new Set(["failed", "cancelled", "canceled", "dismissed"]);
 13→
 14→const toLocalStatus = (raw: string | null | undefined) => {
 15→  const normalized = (raw || "").toLowerCase();
 16→  if (PAID_STATUSES.has(normalized)) return "paid";
 17→  if (FAILED_STATUSES.has(normalized)) return normalized === "canceled" ? "cancelled" : normalized;
 18→  return null;
 19→};
 20→
 21→const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
 22→
 23→Deno.serve(async (req) => {
 24→  if (req.method === "OPTIONS") {
 25→    return new Response(null, { headers: corsHeaders });
 26→  }
 27→
 28→  try {
 29→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL");
 30→    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY");
 31→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
 32→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
 33→    const DODO_ENV = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";
 34→
 35→    if (!SUPABASE_URL || !SUPABASE_ANON_KEY || !SUPABASE_SERVICE_ROLE_KEY || !DODO_API_KEY) {
 36→      return new Response(JSON.stringify({ error: "Server configuration error" }), {
 37→        status: 500,
 38→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 39→      });
 40→    }
 41→
 42→    const authHeader = req.headers.get("Authorization");
 43→    if (!authHeader) {
 44→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
 45→        status: 401,
 46→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 47→      });
 48→    }
 49→
 50→    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
 51→      global: { headers: { Authorization: authHeader } },
 52→    });
 53→
 54→    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
 55→    if (userError || !user) {
 56→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
 57→        status: 401,
 58→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 59→      });
 60→    }
 61→
 62→    const body = await req.json().catch(() => ({}));
 63→    const paymentId = typeof body.payment_id === "string" ? body.payment_id : null;
 64→    const localPaymentId = typeof body.local_payment_id === "string" ? body.local_payment_id : null;
 65→    const checkoutSessionIdInput = typeof body.checkout_session_id === "string" ? body.checkout_session_id : null;
 66→
 67→    if (!paymentId && !localPaymentId && !checkoutSessionIdInput) {
 68→      return new Response(JSON.stringify({ error: "payment_id, local_payment_id, or checkout_session_id is required" }), {
 69→        status: 400,
 70→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 71→      });
 72→    }
 73→
 74→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 75→
 76→    const baseUrl = DODO_ENV === "live_mode"
 77→      ? "https://live.dodopayments.com"
 78→      : "https://test.dodopayments.com";
 79→
 80→    // ── Step 1: find local payment record ────────────────────────────────────
 81→    let paymentRow: Record<string, any> | null = null;
 82→
 83→    if (localPaymentId) {
 84→      const { data } = await supabase
 85→        .from("payments")
 86→        .select("*")
 87→        .eq("id", localPaymentId)
 88→        .eq("user_id", user.id)
 89→        .maybeSingle();
 90→      paymentRow = data || null;
 91→    }
 92→
 93→    if (!paymentRow && checkoutSessionIdInput) {
 94→      const { data } = await supabase
 95→        .from("payments")
 96→        .select("*")
 97→        .eq("dodo_checkout_session_id", checkoutSessionIdInput)
 98→        .eq("user_id", user.id)
 99→        .maybeSingle();
100→      paymentRow = data || null;
101→    }
102→
103→    if (!paymentRow && paymentId) {
104→      const { data } = await supabase
105→        .from("payments")
106→        .select("*")
107→        .eq("dodo_payment_id", paymentId)
108→        .eq("user_id", user.id)
109→        .maybeSingle();
110→      paymentRow = data || null;
111→    }
112→
113→    if (!paymentRow) {
114→      return new Response(JSON.stringify({ error: "Payment record not found for current user" }), {
115→        status: 404,
116→        headers: { ...corsHeaders, "Content-Type": "application/json" },
117→      });
118→    }
119→
120→    // ── Step 2: if already paid in DB (webhook beat us here) — return now ───
121→    if (paymentRow.status === "paid") {
122→      return new Response(JSON.stringify({
123→        success: true,
124→        local_payment_id: paymentRow.id,
125→        dodo_payment_id: paymentRow.dodo_payment_id,
126→        checkout_session_id: paymentRow.dodo_checkout_session_id,
127→        dodo_status: "paid",
128→        local_status: "paid",
129→        credits_added: false,
130→      }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
131→    }
132→
133→    // ── Step 3: find the Dodo payment_id to query ────────────────────────────
134→    // For subscriptions Dodo doesn't include payment_id in the redirect URL,
135→    // so we need to search by checkout_session_id on Dodo's payments list API.
136→    let dodoPayment: Record<string, any> | null = null;
137→
138→    const dodoPaymentIdToFetch = paymentId || paymentRow.dodo_payment_id || null;
139→    const sessionIdToSearch = checkoutSessionIdInput || paymentRow.dodo_checkout_session_id || null;
140→
141→    // ── Step 3a: direct fetch by payment_id if we have it ────────────────────
142→    if (dodoPaymentIdToFetch) {
143→      const res = await fetch(`${baseUrl}/payments/${encodeURIComponent(dodoPaymentIdToFetch)}`, {
144→        headers: { Authorization: `Bearer ${DODO_API_KEY}`, "Content-Type": "application/json" },
145→      });
146→      if (res.ok) {
147→        dodoPayment = await res.json();
148→        console.log("Fetched Dodo payment by ID:", dodoPayment?.payment_id, "status:", dodoPayment?.status);
149→      } else {
150→        const errText = await res.text();
151→        console.error("Dodo payment fetch by ID failed:", res.status, errText);
152→        await logSystemError({
153→          function_name: "verify-dodo-payment",
154→          error_type: "PAYMENT_FETCH",
155→          severity: "warning",
156→          error_message: `Dodo payment fetch by ID failed: ${res.status} ${errText}`,
157→          user_id: user.id,
158→        });
159→      }
160→    }
161→
162→    // ── Step 3b: search by checkout_session_id (subscription case) ───────────
163→    // Dodo payments list supports ?checkout_session_id= filter
164→    if (!dodoPayment && sessionIdToSearch) {
165→      const listRes = await fetch(`${baseUrl}/payments?checkout_session_id=${encodeURIComponent(sessionIdToSearch)}&page_size=5`, {
166→        headers: { Authorization: `Bearer ${DODO_API_KEY}`, "Content-Type": "application/json" },
167→      });
168→      if (listRes.ok) {
169→        const listData = await listRes.json();
170→        // Response is either { items: [...] } or an array directly
171→        const items: any[] = Array.isArray(listData) ? listData : (listData.items || listData.data || []);
172→        if (items.length > 0) {
173→          dodoPayment = items[0];
174→          console.log("Found Dodo payment via session search:", dodoPayment?.payment_id, "status:", dodoPayment?.status);
175→        } else {
176→          console.log("No Dodo payment found for session yet, will retry");
177→        }
178→      } else {
179→        console.warn("Dodo payment list by session failed:", listRes.status, await listRes.text());
180→      }
181→    }
182→
183→    // ── Step 3c: retry loop — subscriptions take a few seconds to register ───
184→    // If we still have no Dodo payment, retry up to 5 times with 2s gaps
185→    if (!dodoPayment && sessionIdToSearch) {
186→      for (let attempt = 1; attempt <= 5; attempt++) {
187→        await sleep(2000);
188→        console.log(`Retry ${attempt}/5 polling Dodo for session ${sessionIdToSearch}`);
189→
190→        const listRes = await fetch(`${baseUrl}/payments?checkout_session_id=${encodeURIComponent(sessionIdToSearch)}&page_size=5`, {
191→          headers: { Authorization: `Bearer ${DODO_API_KEY}`, "Content-Type": "application/json" },
192→        });
193→        if (listRes.ok) {
194→          const listData = await listRes.json();
195→          const items: any[] = Array.isArray(listData) ? listData : (listData.items || listData.data || []);
196→          if (items.length > 0) {
197→            dodoPayment = items[0];
198→            console.log("Found payment on retry", attempt, ":", dodoPayment?.payment_id, dodoPayment?.status);
199→            break;
200→          }
201→        }
202→
203→        // Also check local DB — webhook may have arrived during our sleep
204→        const { data: refreshed } = await supabase
205→          .from("payments")
206→          .select("*")
207→          .eq("id", paymentRow.id)
208→          .single();
209→        if (refreshed?.status === "paid") {
210→          console.log("Webhook marked payment paid during retry loop");
211→          return new Response(JSON.stringify({
212→            success: true,
213→            local_payment_id: refreshed.id,
214→            dodo_payment_id: refreshed.dodo_payment_id,
215→            checkout_session_id: refreshed.dodo_checkout_session_id,
216→            dodo_status: "paid",
217→            local_status: "paid",
218→            credits_added: false,
219→          }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
220→        }
221→      }
222→    }
223→
224→    // ── Step 4: if we still have no Dodo payment data, return pending ─────────
225→    if (!dodoPayment) {
226→      console.warn("Could not fetch Dodo payment after retries — returning pending");
227→      return new Response(JSON.stringify({
228→        success: true,
229→        local_payment_id: paymentRow.id,
230→        dodo_status: null,
231→        local_status: paymentRow.status, // 'created' — frontend will keep polling
232→        credits_added: false,
233→      }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
234→    }
235→
236→    // ── Step 5: store dodo_payment_id if we just discovered it ───────────────
237→    const resolvedPaymentId = dodoPayment.payment_id || dodoPayment.id || dodoPaymentIdToFetch || null;
238→    const resolvedSessionId = dodoPayment.checkout_session_id || sessionIdToSearch || null;
239→    const resolvedSubscriptionId = dodoPayment.subscription_id || null;
240→
241→    const updatePayload: Record<string, any> = {};
242→    if (resolvedPaymentId && paymentRow.dodo_payment_id !== resolvedPaymentId) updatePayload.dodo_payment_id = resolvedPaymentId;
243→    if (resolvedSessionId && paymentRow.dodo_checkout_session_id !== resolvedSessionId) updatePayload.dodo_checkout_session_id = resolvedSessionId;
244→    if (Object.keys(updatePayload).length > 0) {
245→      await supabase.from("payments").update(updatePayload).eq("id", paymentRow.id);
246→    }
247→
248→    // ── Step 6: process paid status ──────────────────────────────────────────
249→    const dodoStatus = toLocalStatus(dodoPayment.status);
250→    let becamePaid = false;
251→    let finalStatus = paymentRow.status;
252→
253→    if (dodoStatus === "paid") {
254→      // Atomic update: only fires if not already paid (idempotent)
255→      const { data: paidUpdate } = await supabase
256→        .from("payments")
257→        .update({
258→          status: "paid",
259→          ...(resolvedPaymentId ? { dodo_payment_id: resolvedPaymentId } : {}),
260→          ...(resolvedSessionId ? { dodo_checkout_session_id: resolvedSessionId } : {}),
261→        })
262→        .eq("id", paymentRow.id)
263→        .neq("status", "paid")
264→        .select("id")
265→        .maybeSingle();
266→
267→      becamePaid = !!paidUpdate;
268→      finalStatus = "paid";
269→
270→      if (becamePaid) {
271→        // Add credits to the correct bucket:
272→        // - plan purchase → subscription_credits (reset monthly)
273→        // - pack purchase → topup_credits (never expire)
274→        const creditField = paymentRow.plan_id ? "subscription_credits" : "topup_credits";
275→        const { data: profile } = await supabase
276→          .from("profiles")
277→          .select("credits, subscription_credits, topup_credits")
278→          .eq("user_id", paymentRow.user_id)
279→          .single();
280→
281→        if (profile) {
282→          await supabase
283→            .from("profiles")
284→            .update({
285→              [creditField]: (profile[creditField] ?? 0) + paymentRow.credits_purchased,
286→              credits: (profile.credits ?? 0) + paymentRow.credits_purchased,
287→            })
288→            .eq("user_id", paymentRow.user_id);
289→        }
290→
291→        // Activate subscription if this is a plan payment
292→        if (paymentRow.plan_id) {
293→          const { data: plan } = await supabase
294→            .from("plans")
295→            .select("name, billing_type")
296→            .eq("id", paymentRow.plan_id)
297→            .single();
298→
299→          if (plan) {
300→            const endsAt = new Date();
301→            if (plan.billing_type === "yearly") {
302→              endsAt.setFullYear(endsAt.getFullYear() + 1);
303→            } else {
304→              endsAt.setMonth(endsAt.getMonth() + 1);
305→            }
306→
307→            const profileUpdate: Record<string, any> = {
308→              plan: plan.name,
309→              subscription_ends_at: endsAt.toISOString(),
310→            };
311→            // Store subscription_id if Dodo provided it (may come later via webhook if missing now)
312→            if (resolvedSubscriptionId) {
313→              profileUpdate.dodo_subscription_id = resolvedSubscriptionId;
314→            }
315→
316→            await supabase
317→              .from("profiles")
318→              .update(profileUpdate)
319→              .eq("user_id", paymentRow.user_id);
320→
321→            console.log("Subscription activated for user:", paymentRow.user_id, "plan:", plan.name, "subscription_id:", resolvedSubscriptionId || "(pending webhook)");
322→          }
323→        }
324→      }
325→    } else if (dodoStatus && dodoStatus !== paymentRow.status) {
326→      await supabase
327→        .from("payments")
328→        .update({ status: dodoStatus })
329→        .eq("id", paymentRow.id);
330→      finalStatus = dodoStatus;
331→    }
332→
333→    return new Response(JSON.stringify({
334→      success: true,
335→      local_payment_id: paymentRow.id,
336→      dodo_payment_id: resolvedPaymentId,
337→      checkout_session_id: resolvedSessionId,
338→      dodo_status: dodoPayment.status || null,
339→      local_status: finalStatus,
340→      credits_added: becamePaid,
341→    }), {
342→      headers: { ...corsHeaders, "Content-Type": "application/json" },
343→    });
344→
345→  } catch (err: unknown) {
346→    console.error("verify-dodo-payment error:", err);
347→    await logSystemError({
348→      function_name: "verify-dodo-payment",
349→      error_type: "PAYMENT_ERROR",
350→      severity: "critical",
351→      error_message: errorToMessage(err),
352→      error_stack: errorToStack(err),
353→    });
354→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
355→      status: 500,
356→      headers: { ...corsHeaders, "Content-Type": "application/json" },
357→    });
358→  }
359→});
