328→                        ) : (
329→                          <>
330→                            Subscribe <ArrowRight className="h-3 w-3" />
331→                          </>
332→                        )}
333→                      </Button>
334→                    )}
335→                  </div>
336→                </div>
337→              );
338→            })}
339→            {(!plans || plans.length === 0) && (
340→              <p className="text-sm text-muted-foreground text-center py-4">
341→                No subscription plans available right now.
342→              </p>
343→            )}
344→          </div>
345→
346→          <p className="text-[11px] text-muted-foreground text-center pt-1">
347→            All plans auto-renew. Cancel anytime before your next billing date.
348→          </p>
349→        </DialogContent>
350→      </Dialog>
351→
352→      {/* Confirmation AlertDialog */}
353→      <AlertDialog open={confirmAction !== null} onOpenChange={(o) => !o && setConfirmAction(null)}>
354→        <AlertDialogContent>
355→          <AlertDialogHeader>
356→            <AlertDialogTitle>
357→              {confirmAction?.type === "upgrade"
358→                ? `Subscribe to ${confirmAction.planName}?`
359→                : confirmAction?.type === "cancel_subscription"
360→                  ? "Cancel Auto-Renewal?"
361→                  : "Switch to Pay As You Go?"}
362→            </AlertDialogTitle>
363→            <AlertDialogDescription>
364→              {confirmAction?.type === "upgrade" ? (
365→                <>
366→                  You'll be redirected to our secure checkout page to complete payment of{" "}
367→                  <span className="font-semibold text-foreground">${confirmAction.price}</span>.
368→                  Your subscription will auto-renew each billing period.
369→                </>
370→              ) : confirmAction?.type === "cancel_subscription" ? (
371→                <>
372→                  Your subscription will remain active until the end of your current billing period.
373→                  After that, you'll be switched to Pay As You Go pricing. Your remaining credits will be preserved.
374→                </>
375→              ) : (
376→                <>
377→                  You'll switch back to Pay As You Go pricing at <span className="font-semibold text-foreground">${paygCost}/resume</span>.
378→                  Your remaining credits will be preserved and you can still purchase credit top-ups.
379→                  {hasActiveSubscription && " Your active subscription will also be cancelled."}
380→                </>
381→              )}
382→            </AlertDialogDescription>
383→          </AlertDialogHeader>
384→          <AlertDialogFooter>
385→            <AlertDialogCancel>Keep Current Plan</AlertDialogCancel>
386→            <AlertDialogAction
387→              onClick={handleConfirmedAction}
388→              disabled={downgrading || cancelling}
389→              className={confirmAction?.type !== "upgrade" ? "bg-destructive text-destructive-foreground hover:bg-destructive/90" : ""}
390→            >
391→              {(downgrading || cancelling) && <Loader2 className="h-4 w-4 animate-spin mr-1" />}
392→              {confirmAction?.type === "upgrade"
393→                ? "Proceed to Payment"
394→                : confirmAction?.type === "cancel_subscription"
395→                  ? "Cancel Auto-Renewal"
396→                  : "Confirm Downgrade"}
397→            </AlertDialogAction>
398→          </AlertDialogFooter>
399→        </AlertDialogContent>
400→      </AlertDialog>
401→    </>
402→  );
403→};
