  1→ // @ts-nocheck
  2→// deno-lint-ignore-file no-explicit-any
  3→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
  4→import DodoPayments from "https://esm.sh/dodopayments@2.4.1";
  5→import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
  6→
  7→const corsHeaders = {
  8→  "Access-Control-Allow-Origin": "*",
  9→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, webhook-id, webhook-signature, webhook-timestamp",
 10→};
 11→
 12→Deno.serve(async (req) => {
 13→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 14→
 15→  try {
 16→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 17→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 18→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
 19→    const WEBHOOK_KEY = Deno.env.get("DODO_PAYMENTS_WEBHOOK_KEY") || Deno.env.get("DODO_PAYMENTS_WEBHOOK_SECRET");
 20→
 21→    if (!DODO_API_KEY) {
 22→      console.error("DODO_PAYMENTS_API_KEY is not configured");
 23→      await logSystemError({
 24→        function_name: "dodo-webhook",
 25→        error_type: "MISSING_CONFIG",
 26→        severity: "critical",
 27→        error_message: "DODO_PAYMENTS_API_KEY is not configured",
 28→      });
 29→      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
 30→    }
 31→    if (!WEBHOOK_KEY) {
 32→      console.error("DODO_PAYMENTS_WEBHOOK_KEY/SECRET is not configured");
 33→      await logSystemError({
 34→        function_name: "dodo-webhook",
 35→        error_type: "MISSING_CONFIG",
 36→        severity: "critical",
 37→        error_message: "DODO_PAYMENTS_WEBHOOK_KEY/SECRET is not configured",
 38→      });
 39→      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
 40→    }
 41→
 42→    const rawBody = await req.text();
 43→    const webhookHeaders = {
 44→      "webhook-id": req.headers.get("webhook-id") || "",
 45→      "webhook-signature": req.headers.get("webhook-signature") || "",
 46→      "webhook-timestamp": req.headers.get("webhook-timestamp") || "",
 47→    };
 48→
 49→    const dodo = new DodoPayments({
 50→      bearerToken: DODO_API_KEY,
 51→      webhookKey: WEBHOOK_KEY,
 52→    });
 53→
 54→    let unwrapped: any;
 55→    try {
 56→      unwrapped = dodo.webhooks.unwrap(rawBody, { headers: webhookHeaders });
 57→    } catch (e) {
 58→      console.error("Invalid webhook signature", e);
 59→      await logSystemError({
 60→        function_name: "dodo-webhook",
 61→        error_type: "WEBHOOK_VALIDATION",
 62→        severity: "critical",
 63→        error_message: errorToMessage(e),
 64→        error_stack: errorToStack(e),
 65→      });
 66→      return new Response("Invalid signature", { status: 401, headers: corsHeaders });
 67→    }
 68→
 69→    const eventType: string = unwrapped.type || "unknown";
 70→    const payload: Record<string, unknown> = unwrapped.data || {};
 71→    const webhookId = webhookHeaders["webhook-id"];
 72→
 73→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 74→
 75→    // Idempotency: skip if we've already processed this exact webhook-id
 76→    if (webhookId) {
 77→      const { data: dupList } = await supabase
 78→        .from("subscription_webhooks")
 79→        .select("id")
 80→        .eq("gateway", "dodo")
 81→        .eq("webhook_id", webhookId)
 82→        .limit(1);
 83→      if (dupList && dupList.length > 0) {
 84→        console.log(`Duplicate webhook ${webhookId}, skipping`);
 85→        return new Response("OK", { status: 200, headers: corsHeaders });
 86→      }
 87→    }
 88→
 89→    const subscriptionIdForLog = (payload["subscription_id"] as string | undefined) || null;
 90→
 91→    // Log the event (unprocessed)
 92→    const logInsert = await supabase
 93→      .from("subscription_webhooks")
 94→      .insert({
 95→        event_type: eventType,
 96→        payload: unwrapped,
 97→        gateway: "dodo",
 98→        processed: false,
 99→        dodo_subscription_id: subscriptionIdForLog,
100→        webhook_id: webhookId || null,
101→      })
102→      .select("id")
103→      .single();
104→
105→    const logId: string | null = logInsert.data?.id ?? null;
106→
107→    async function markProcessed(userId?: string | null) {
108→      if (!logId) return;
109→      await supabase
110→        .from("subscription_webhooks")
111→        .update({ processed: true, user_id: userId ?? null })
112→        .eq("id", logId);
113→    }
114→
115→    // Prefer correlation via metadata.local_payment_id (set at checkout creation)
116→    const meta = (payload["metadata"] as Record<string, string> | undefined) || {};
117→    const localPaymentId = (meta["local_payment_id"] as string | undefined) || null;
118→
119→    if (eventType === "payment.succeeded" || eventType === "payment_succeeded") {
120→      const paymentId = (payload["payment_id"] as string | undefined) || null;
121→
122→      let paymentRow: any = null;
123→      if (localPaymentId) {
124→        const { data } = await supabase.from("payments").select("*").eq("id", localPaymentId).single();
125→        paymentRow = data;
126→      } else if (paymentId) {
127→        const { data } = await supabase.from("payments").select("*").eq("dodo_payment_id", paymentId).single();
128→        paymentRow = data;
129→      }
130→
131→      if (paymentRow) {
132→        // Atomic status transition: only the first delivery wins (idempotent on retries)
133→        const { data: paidUpdate } = await supabase
134→          .from("payments")
135→          .update({
136→            status: "paid",
137→            ...(paymentId && !paymentRow.dodo_payment_id ? { dodo_payment_id: paymentId } : {}),
138→          })
139→          .eq("id", paymentRow.id)
140→          .neq("status", "paid")
141→          .select("id")
142→          .maybeSingle();
143→        const newlyPaid = !!paidUpdate;
144→
145→        if (newlyPaid) {
146→          // Increment credits once (idempotent on status transition)
147→          // Plan purchase → subscription_credits; pack purchase → topup_credits
148→          const creditField = paymentRow.plan_id ? "subscription_credits" : "topup_credits";
149→          const { data: profile } = await supabase
150→            .from("profiles")
151→            .select("credits, subscription_credits, topup_credits")
152→            .eq("user_id", paymentRow.user_id)
153→            .single();
154→
155→          if (profile) {
156→            await supabase
157→              .from("profiles")
158→              .update({
159→                [creditField]: ((profile as any)[creditField] ?? 0) + paymentRow.credits_purchased,
160→                credits: (profile.credits ?? 0) + paymentRow.credits_purchased,
161→              })
162→              .eq("user_id", paymentRow.user_id);
163→          }
164→
165→          // Activate plan if applicable
166→          if (paymentRow.plan_id) {
167→            const { data: plan } = await supabase
168→              .from("plans")
169→              .select("name, billing_type")
170→              .eq("id", paymentRow.plan_id)
171→              .single();
172→
173→            if (plan) {
174→              const endsAt = new Date();
175→              if (plan.billing_type === "yearly") {
176→                endsAt.setFullYear(endsAt.getFullYear() + 1);
177→              } else {
178→                endsAt.setMonth(endsAt.getMonth() + 1);
179→              }
180→              await supabase
181→                .from("profiles")
182→                .update({
183→                  plan: plan.name,
184→                  subscription_ends_at: endsAt.toISOString(),
185→                  dodo_subscription_id: (payload["subscription_id"] as string | undefined) || null,
186→                })
187→                .eq("user_id", paymentRow.user_id);
188→            }
189→          }
190→        }
191→
192→        await markProcessed(paymentRow.user_id);
193→      }
194→    } else if (eventType === "payment.failed" || eventType === "payment_failed") {
195→      const paymentId = (payload["payment_id"] as string | undefined) || null;
196→      if (localPaymentId) {
197→        await supabase
198→          .from("payments")
199→          .update({ status: "failed", dodo_payment_id: paymentId })
200→          .eq("id", localPaymentId);
201→      } else if (paymentId) {
202→        await supabase.from("payments").update({ status: "failed" }).eq("dodo_payment_id", paymentId);
203→      }
204→      await markProcessed(null);
205→    } else if (eventType === "subscription.renewed" || eventType === "subscription_renewed") {
206→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
207→      if (subscriptionId) {
208→        const { data: profile } = await supabase
209→          .from("profiles")
210→          .select("user_id, plan, credits, subscription_credits")
211→          .eq("dodo_subscription_id", subscriptionId)
212→          .single();
213→
214→        if (profile) {
215→          const { data: plan } = await supabase
216→            .from("plans")
217→            .select("credits, billing_type")
218→            .eq("name", profile.plan)
219→            .single();
220→
221→          if (plan) {
222→            const endsAt = new Date();
223→            if (plan.billing_type === "yearly") {
224→              endsAt.setFullYear(endsAt.getFullYear() + 1);
225→            } else {
226→              endsAt.setMonth(endsAt.getMonth() + 1);
227→            }
228→            // Renewal resets subscription_credits to plan amount (monthly allowance, not cumulative).
229→            // Only add the net delta to total credits so topup_credits and total stay accurate.
230→            const currentSub = (profile as any).subscription_credits ?? 0;
231→            const subDelta = plan.credits - currentSub;
232→            await supabase
233→              .from("profiles")
234→              .update({
235→                subscription_credits: plan.credits,
236→                credits: (profile.credits ?? 0) + subDelta,
237→                subscription_ends_at: endsAt.toISOString(),
238→              })
239→              .eq("user_id", profile.user_id);
240→          }
241→        }
242→      }
243→      await markProcessed(null);
244→    } else if (
245→      eventType === "subscription.cancelled" ||
246→      eventType === "subscription_cancelled" ||
247→      eventType === "subscription.on_hold" ||
248→      eventType === "subscription.failed"
249→    ) {
250→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
251→      if (subscriptionId) {
252→        // For on_hold/failed: downgrade immediately; for cancelled, let expiry task handle downgrade.
253→        if (eventType.includes("on_hold") || eventType.includes("failed")) {
254→          await supabase
255→            .from("profiles")
256→            .update({
257→              plan: "free",
258→              dodo_subscription_id: null,
259→              subscription_ends_at: null,
260→            })
261→            .eq("dodo_subscription_id", subscriptionId);
262→        }
263→      }
264→      await markProcessed(null);
265→    } else if (eventType === "subscription.active" || eventType === "subscription_active") {
266→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
267→      if (subscriptionId && localPaymentId) {
268→        const { data: payment } = await supabase.from("payments").select("user_id").eq("id", localPaymentId).single();
269→        if (payment) {
270→          await supabase.from("profiles").update({ dodo_subscription_id: subscriptionId }).eq("user_id", payment.user_id);
271→          await markProcessed(payment.user_id);
272→        }
273→      }
274→    }
275→
276→    return new Response("OK", { status: 200, headers: corsHeaders });
277→  } catch (err) {
278→    console.error("dodo-webhook error:", err);
279→    await logSystemError({
280→      function_name: "dodo-webhook",
281→      error_type: "PAYMENT_ERROR",
282→      severity: "critical",
283→      error_message: errorToMessage(err),
284→      error_stack: errorToStack(err),
285→    });
286→    return new Response("Internal error", { status: 500, headers: corsHeaders });
287→  }
288→});
