31→      });
32→    }
33→
34→    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
35→      global: { headers: { Authorization: authHeader } },
36→    });
37→    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
38→    if (userError || !user) {
39→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
40→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
41→      });
42→    }
