 1→import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
 2→import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
 3→
 4→const corsHeaders = {
 5→  "Access-Control-Allow-Origin": "*",
 6→  "Access-Control-Allow-Headers":
 7→    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
 8→};
 9→
10→Deno.serve(async (req) => {
11→  if (req.method === "OPTIONS") {
12→    return new Response(null, { headers: corsHeaders });
13→  }
14→
15→  try {
16→    const serviceClient = createClient(
17→      Deno.env.get("SUPABASE_URL")!,
18→      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
19→    );
20→
21→    // Find all profiles with expired subscriptions that are still on a paid plan
22→    const { data: expired, error } = await serviceClient
23→      .from("profiles")
24→      .select("id, user_id, plan, subscription_ends_at")
25→      .neq("plan", "free")
26→      .not("subscription_ends_at", "is", null)
27→      .lt("subscription_ends_at", new Date().toISOString());
28→
29→    if (error) {
30→      console.error("Query error:", error.message);
31→      await logSystemError({
32→        function_name: "check-expired-subscriptions",
33→        error_type: "QUERY_ERROR",
34→        severity: "critical",
35→        error_message: `Query error: ${error.message}`,
36→      });
37→      return new Response(JSON.stringify({ error: error.message }), {
38→        status: 500,
39→        headers: { ...corsHeaders, "Content-Type": "application/json" },
40→      });
41→    }
42→
43→    if (!expired || expired.length === 0) {
44→      return new Response(JSON.stringify({ downgraded: 0 }), {
45→        headers: { ...corsHeaders, "Content-Type": "application/json" },
46→      });
47→    }
48→
49→    // Downgrade all expired users to free/PAYG
50→    const userIds = expired.map((p) => p.user_id);
51→    const { error: updateError } = await serviceClient
52→      .from("profiles")
53→      .update({ plan: "free", subscription_ends_at: null, dodo_subscription_id: null })
54→      .in("user_id", userIds);
55→
56→    if (updateError) {
57→      console.error("Update error:", updateError.message);
58→      await logSystemError({
59→        function_name: "check-expired-subscriptions",
60→        error_type: "UPDATE_ERROR",
61→        severity: "critical",
62→        error_message: `Update error: ${updateError.message}`,
63→      });
64→      return new Response(JSON.stringify({ error: updateError.message }), {
65→        status: 500,
66→        headers: { ...corsHeaders, "Content-Type": "application/json" },
67→      });
68→    }
69→
70→    console.log(`Auto-downgraded ${expired.length} expired subscriptions`);
71→
72→    return new Response(
73→      JSON.stringify({ downgraded: expired.length, user_ids: userIds }),
74→      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
75→    );
76→  } catch (err: unknown) {
77→    console.error("Error:", err);
78→    await logSystemError({
79→      function_name: "check-expired-subscriptions",
80→      error_type: "SUBSCRIPTION_EXPIRY_ERROR",
81→      severity: "critical",
82→      error_message: errorToMessage(err),
83→      error_stack: errorToStack(err),
84→    });
85→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
86→      status: 500,
87→      headers: { ...corsHeaders, "Content-Type": "application/json" },
88→    });
89→  }
90→});
