 16→const BillingTab = () => {
 17→  const qc = useQueryClient();
 18→  const [fetchingBrands, setFetchingBrands] = useState(false);
 19→  const [brands, setBrands] = useState<any[] | null>(null);
 20→  const [savingBrand, setSavingBrand] = useState(false);
 21→
 22→  const { data: config } = useQuery({
 23→    queryKey: ["platform_config_brand"],
 24→    queryFn: async () => {
 25→      const { data, error } = await supabase.from("platform_config").select("dodo_brand_id").limit(1).single();
 26→      if (error) return null;
 27→      return data;
 28→    },
 29→  });
 30→
 31→  const fetchBrands = async () => {
 32→    setFetchingBrands(true);
 33→    try {
 34→      const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
 35→        body: { action: "fetch_brands" },
 36→      });
 37→      if (error) throw error;
 38→      if (data?.error) throw new Error(data.error);
 39→      const brandList = Array.isArray(data?.brands) ? data.brands : data?.brands?.items || [];
 40→      setBrands(brandList);
 41→      if (brandList.length === 0) toast.info("No brands found on Dodo. Create one in Dodo Dashboard first.");
 42→    } catch (err: any) {
 43→      toast.error("Failed to fetch brands: " + (err.message || "Unknown error"));
 44→    } finally {
 45→      setFetchingBrands(false);
 46→    }
 47→  };
 48→
 49→  const saveBrandId = async (brandId: string) => {
 50→    setSavingBrand(true);
 51→    try {
 52→      const { error } = await supabase.from("platform_config").update({ dodo_brand_id: brandId } as any).not("id", "is", null);
 53→      if (error) throw error;
 54→      toast.success("Dodo brand saved ✓");
 55→      qc.invalidateQueries({ queryKey: ["platform_config_brand"] });
 56→    } catch (err: any) {
 57→      toast.error("Failed to save brand: " + (err.message || "Unknown error"));
 58→    } finally {
 59→      setSavingBrand(false);
 60→    }
 61→  };
 62→
 63→  return (
 64→    <div className="space-y-4">
 65→      <h2 className="text-xl font-semibold">Billing & Plans</h2>
 66→
 67→      {/* Dodo Brand Config */}
 68→      <Card>
 69→        <CardHeader className="pb-3">
 70→          <CardTitle className="text-sm flex items-center gap-2">
 71→            <Store className="h-4 w-4 text-primary" />
 72→            Dodo Brand
 73→          </CardTitle>
 74→        </CardHeader>
 75→        <CardContent>
 76→          <div className="flex items-center gap-3 flex-wrap">
 77→            {config?.dodo_brand_id ? (
 78→              <div className="flex items-center gap-2">
 79→                <Badge variant="secondary" className="gap-1 text-xs">
 80→                  <CheckCircle className="h-3 w-3 text-emerald-600" />
 81→                  {config.dodo_brand_id}
 82→                </Badge>
 83→                <span className="text-xs text-muted-foreground">All products auto-attach this brand</span>
 84→              </div>
 85→            ) : (
 86→              <span className="text-sm text-muted-foreground">No brand configured — products will be created without a brand.</span>
 87→            )}
 88→            <Button variant="outline" size="sm" onClick={fetchBrands} disabled={fetchingBrands}>
 89→              {fetchingBrands ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : <RefreshCw className="h-3.5 w-3.5 mr-1" />}
 90→              Fetch Brands
 91→            </Button>
 92→          </div>
 93→
 94→          {brands && brands.length > 0 && (
 95→            <div className="mt-3 flex flex-wrap gap-2">
 96→              {brands.map((b: any) => (
 97→                <Button
 98→                  key={b.id || b.brand_id}
 99→                  variant={config?.dodo_brand_id === (b.id || b.brand_id) ? "default" : "outline"}
100→                  size="sm"
101→                  className="text-xs"
102→                  disabled={savingBrand}
103→                  onClick={() => saveBrandId(b.id || b.brand_id)}
104→                >
105→                  {b.name || b.id || b.brand_id}
106→                </Button>
107→              ))}
108→            </div>
109→          )}
110→
111→          {brands && brands.length === 0 && (
112→            <div className="mt-2">
113→              <p className="text-xs text-muted-foreground">No brands found. You can manually enter a brand ID:</p>
114→              <div className="flex gap-2 mt-1">
115→                <Input
116→                  placeholder="Brand ID from Dodo Dashboard"
117→                  className="max-w-xs text-xs"
118→                  onKeyDown={(e) => {
119→                    if (e.key === "Enter") {
120→                      const val = (e.target as HTMLInputElement).value.trim();
121→                      if (val) saveBrandId(val);
122→                    }
123→                  }}
124→                />
125→              </div>
126→            </div>
127→          )}
128→        </CardContent>
129→      </Card>
130→
131→      <Tabs defaultValue="plans">
132→        <TabsList>
