135→          <TabsTrigger value="payments">Payments</TabsTrigger>
136→          <TabsTrigger value="subscriptions">Subscriptions</TabsTrigger>
137→        </TabsList>
138→        <TabsContent value="plans"><PlansTab /></TabsContent>
139→        <TabsContent value="wallet"><WalletSettingsTab /></TabsContent>
140→        <TabsContent value="payments"><PaymentsTab /></TabsContent>
141→        <TabsContent value="subscriptions"><SubscriptionsSubTab /></TabsContent>
142→      </Tabs>
143→    </div>
144→  );
145→};
