56→      return new Response(JSON.stringify({ error: "Profile not found" }), {
57→        status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
58→      });
59→    }
60→    const newCredits = Math.max(0, (profile.credits ?? 0) + credits);
61→    const { error } = await supabase.from("profiles").update({ credits: newCredits }).eq("user_id", targetUser.id);
62→    if (error) throw error;
63→
64→    return new Response(JSON.stringify({ success: true }), {
65→      headers: { ...corsHeaders, "Content-Type": "application/json" },
66→    });
67→  } catch (err: unknown) {
68→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
69→      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
70→    });
71→  }
72→});
