  9→async function authenticateAdmin(req: Request) {
 10→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 11→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 12→  const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
 13→
 14→  const authHeader = req.headers.get("Authorization");
 15→  if (!authHeader?.startsWith("Bearer ")) throw new Error("No auth");
 16→
 17→  const supabaseUser = createClient(SUPABASE_URL, anonKey, {
 18→    global: { headers: { Authorization: authHeader } },
 19→  });
 20→  const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
 21→  if (userError || !user) throw new Error("Unauthorized");
 22→  const adminUserId = user.id;
 23→
 24→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 25→
 26→  const { data: roles } = await supabase.from("user_roles").select("role").eq("user_id", adminUserId);
 27→  if (!roles?.some((r: any) => r.role === "admin")) {
 28→    throw new Error("Admin access required");
 29→  }
 30→
 31→  return { supabase, adminUserId };
 32→}
