 1→-- Split unified credits into subscription_credits (monthly, spend first) and topup_credits (never expire, spend last)
 2→ALTER TABLE public.profiles
 3→  ADD COLUMN IF NOT EXISTS subscription_credits integer NOT NULL DEFAULT 0,
 4→  ADD COLUMN IF NOT EXISTS topup_credits integer NOT NULL DEFAULT 0;
 5→
 6→-- Migrate existing credits: treat all current credits as top-up (safe conservative default)
 7→UPDATE public.profiles SET topup_credits = credits WHERE credits > 0;
 8→
 9→-- Replace deduct_credits: consume subscription_credits first, then topup_credits
10→CREATE OR REPLACE FUNCTION public.deduct_credits(_user_id UUID, _job_id UUID, _amount INTEGER)
11→RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
12→DECLARE
13→  sub_c   INTEGER;
14→  top_c   INTEGER;
15→  from_sub INTEGER;
16→  from_top INTEGER;
17→BEGIN
18→  SELECT subscription_credits, topup_credits
19→    INTO sub_c, top_c
20→    FROM public.profiles
21→    WHERE user_id = _user_id
22→    FOR UPDATE;
23→
24→  IF COALESCE(sub_c, 0) + COALESCE(top_c, 0) < _amount THEN
25→    RETURN FALSE;
26→  END IF;
27→
28→  from_sub := LEAST(COALESCE(sub_c, 0), _amount);
29→  from_top := _amount - from_sub;
30→
31→  UPDATE public.profiles
32→    SET subscription_credits = subscription_credits - from_sub,
33→        topup_credits         = topup_credits - from_top,
34→        credits               = credits - _amount,
35→        updated_at            = now()
36→    WHERE user_id = _user_id;
37→
38→  INSERT INTO public.usage_logs (user_id, job_id, credits_used)
39→    VALUES (_user_id, _job_id, _amount);
40→
41→  RETURN TRUE;
42→END;
43→$$;
