147→function extractTotalYears(rolesWithDates: any[]): number {
148→  if (!Array.isArray(rolesWithDates) || rolesWithDates.length === 0) return 0;
149→
150→  const intervals: { start: number; end: number }[] = [];
151→  const currentYear = new Date().getFullYear();
152→  const currentMonth = new Date().getMonth() + 1;
153→
154→  for (const role of rolesWithDates) {
155→    const startRaw = role.start || role.start_date || role.from || "";
156→    const endRaw = role.end || role.end_date || role.to || "";
157→
158→    const startDate = parseDate(String(startRaw), currentYear, currentMonth);
159→    let endDate = parseDate(String(endRaw), currentYear, currentMonth);
160→
161→    // Handle "present", "current", "ongoing" etc.
162→    const endLower = String(endRaw).toLowerCase().trim();
163→    if (!endRaw || endLower === "present" || endLower === "current" || endLower === "ongoing" || endLower === "now" || endLower === "till date" || endLower === "till now") {
164→      endDate = currentYear + (currentMonth - 1) / 12;
165→    }
166→
167→    if (startDate > 0 && endDate > 0 && endDate >= startDate) {
168→      intervals.push({ start: startDate, end: endDate });
169→    }
170→  }
171→
172→  if (intervals.length === 0) return 0;
173→
174→  // Merge overlapping intervals to avoid double-counting
175→  intervals.sort((a, b) => a.start - b.start);
176→  const merged: { start: number; end: number }[] = [intervals[0]];
177→  for (let i = 1; i < intervals.length; i++) {
178→    const last = merged[merged.length - 1];
179→    if (intervals[i].start <= last.end) {
180→      last.end = Math.max(last.end, intervals[i].end);
181→    } else {
182→      merged.push(intervals[i]);
183→    }
184→  }
185→
186→  let totalYears = 0;
187→  for (const iv of merged) {
188→    totalYears += iv.end - iv.start;
189→  }
190→  return Math.round(totalYears * 10) / 10; // 1 decimal
191→}
